const fs = require('fs');
const { Agent, Tool } = require('@voltagent/core');
const { XSAIProvider } = require('@voltagent/xsai');
const { z } = require('zod');

const logPath = '/home/user/app/hooks.log';

const calculateSumTool = new Tool({
  name: 'calculate_sum',
  description: 'Calculates the sum of two numbers',
  parameters: z.object({
    a: z.number(),
    b: z.number(),
  }),
  execute: async ({ a, b }) => {
    return a + b;
  }
});

const provider = new XSAIProvider({
  apiKey: process.env.OPENAI_API_KEY,
  model: 'gpt-4o-mini'
});

const agent = new Agent({
  provider,
  tools: [calculateSumTool],
  hooks: {
    onStart: async () => {
      fs.appendFileSync(logPath, 'HOOK: onStart\n');
    },
    onToolStart: async () => {
      fs.appendFileSync(logPath, 'HOOK: onToolStart - calculate_sum\n');
    },
    onToolEnd: async () => {
      fs.appendFileSync(logPath, 'HOOK: onToolEnd - calculate_sum\n');
    },
    onEnd: async () => {
      fs.appendFileSync(logPath, 'HOOK: onEnd\n');
    }
  }
});

async function main() {
  try {
    await agent.generateText({ prompt: "Calculate the sum of 15 and 27" });
    process.exit(0);
  } catch (err) {
    console.error(err);
    process.exit(1);
  }
}

main();

